import { execFileSync } from "node:child_process";
const sha = process.argv[2];
const sleep = (ms) => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
const deadline = Date.now() + 15 * 60_000;
while (Date.now() < deadline) {
  let out = "";
  try {
    out = execFileSync("gh", ["run", "list", "--repo", "mvhenten/stallion", "--workflow", "deploy.yml", "--limit", "1", "--json", "status,conclusion,headSha,databaseId"], { encoding: "utf8" });
  } catch (e) { console.log("gh error", String(e.stderr || e).slice(0, 200)); sleep(60_000); continue; }
  const [run] = JSON.parse(out);
