import { mkdirSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { chromium, devices } from "playwright";

const ORIGIN = "https://stallion.matthijs-f49.workers.dev";
const board = `pwa-${Date.now().toString(36)}`;
const url = `${ORIGIN}/b/${board}`;
const dir = join(homedir(), "development", ".tmp", "stallion-pwa");
mkdirSync(dir, { recursive: true });
const results = { url };
const errors = [];
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ ...devices["Galaxy Tab S9"] });
await context.addInitScript(() => {
  window.__bip = false;
  window.addEventListener("beforeinstallprompt", () => { window.__bip = true; });
});
const page = await context.newPage();
page.on("console", (m) => { if (m.type() === "error" && !/favicon/.test(m.text())) errors.push(m.text()); });
page.on("pageerror", (e) => errors.push(String(e)));

await page.goto(url, { waitUntil: "load" });
const manifestHref = await page.getAttribute('link[rel="manifest"]', "href");
const manifestRes = await page.request.get(new URL(manifestHref, ORIGIN).href);
const manifest = await manifestRes.json();
results.manifest = { status: manifestRes.status(), contentType: manifestRes.headers()["content-type"], name: manifest.name, start_url: manifest.start_url, icons: manifest.icons.length };

results.swReady = await page.evaluate(async () => {
  const reg = await navigator.serviceWorker.ready;
  return { active: reg.active?.state, scope: reg.scope, script: reg.active?.scriptURL };
});
await page.waitForFunction(() => navigator.serviceWorker.controller !== null, null, { timeout: 15000 }).catch(() => {});
results.controlled = await page.evaluate(() => navigator.serviceWorker.controller !== null);
results.caches = await page.evaluate(async () => {
  const names = await caches.keys();
  const counts = {};
  for (const n of names) counts[n] = (await (await caches.open(n)).keys()).length;
  return counts;
});

const cdp = await context.newCDPSession(page);
results.installabilityErrors = (await cdp.send("Page.getInstallabilityErrors")).installabilityErrors;
await page.screenshot({ path: join(dir, "1-first-load.png") });

await page.reload({ waitUntil: "load" });
results.secondLoad = await page.evaluate(() => {
  const nav = performance.getEntriesByType("navigation")[0];
  const res = performance.getEntriesByType("resource").filter((r) => /\/assets\//.test(r.name));
  return {
    navTransferSize: nav.transferSize,
    assets: res.map((r) => ({ name: r.name.split("/").pop(), transferSize: r.transferSize })),
  };
});
results.secondLoadFromSw = await page.evaluate(() => navigator.serviceWorker.controller !== null);

await page.waitForSelector('.status[data-connection="Connected"]', { timeout: 20000 });
results.syncDot = await page.$eval(".status", (el) => ({ connection: el.dataset.connection, background: getComputedStyle(el).backgroundColor }));

const vp = page.viewportSize();
const clip = { x: vp.width * 0.3, y: vp.height * 0.4, width: vp.width * 0.4, height: vp.height * 0.3 };
const before = await page.screenshot({ clip });
const touch = await context.newCDPSession(page);
const pts = Array.from({ length: 24 }, (_, i) => ({ x: clip.x + 20 + (i / 23) * (clip.width - 40), y: clip.y + clip.height / 2 + Math.sin((i / 23) * Math.PI * 2) * 40 }));
const send = (type, p) => touch.send("Input.dispatchTouchEvent", { type, touchPoints: p ? [{ x: p.x, y: p.y, id: 1, radiusX: 2, radiusY: 2, force: 0.5 }] : [] });
await send("touchStart", pts[0]);
for (const p of pts.slice(1)) { await send("touchMove", p); await sleep(12); }
await send("touchEnd");
await sleep(500);
const after = await page.screenshot({ clip });
results.drew = !before.equals(after);
await page.screenshot({ path: join(dir, "2-drawn.png") });

await sleep(10000 - 0);
results.beforeinstallprompt = await page.evaluate(() => window.__bip);
results.consoleErrors = errors;
console.log(JSON.stringify(results, null, 2));
await browser.close();
EOF
